import{_ as s,l as o,o as t,c as n,v as a,p,x as r,d as l,i as _,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"布鲁斯特角与全内反射","description":"","frontmatter":{"title":"布鲁斯特角与全内反射","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/brewster-tir.md","filePath":"litho/brewster-tir.md","lastUpdated":1789023840000}'),c={name:"litho/brewster-tir.md"};function d(B,e,m,f,E,T){const i=o("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="布鲁斯特角与全内反射" tabindex="-1">布鲁斯特角与全内反射 <a class="header-anchor" href="#布鲁斯特角与全内反射" aria-label="Permalink to &quot;布鲁斯特角与全内反射&quot;">​</a></h1><div class="epigraph"><p>p 偏振在 Brewster 角反射为零；光从光密媒射向光疏媒且入射角超过临界角时，能量全反射，疏媒一侧只留下倏逝场。</p><footer>—— 据 Hecht, Optics 与 Born &amp; Wolf, Principles of Optics 对 Brewster 与全内反射的整理</footer></div><p><a href="/litho/fresnel-coefficients">上一课</a>写出了一般入射角下的 \\(r_s\\)、\\(r_p\\)。本课不重写斯涅尔定律。缺口是两个特殊角：是否存在使 \\(r_p=0\\) 的入射？从密媒射向疏媒时折射角能否超过 \\(90^\\circ\\)，超过之后能量去哪？后课偏振光路、棱镜转向与近场耦合会碰到这两个角。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一般角下 \\(R_s\\neq R_p\\)。工程上常问两件更窄的事：怎样让窗片对 p 光几乎不反射？怎样用一块棱镜把光束「无损」折转？前者是 Brewster 角，后者是全内反射（TIR）。没有临界角，无法理解倏逝波沿法向衰减；没有 Brewster，无法理解「反射光变成纯 s」这条偏振选择。</p><p>投影光刻的主光路通常工作在传播波区，不是靠 TIR 成像。本课把两个角钉在菲涅尔公式上，不把它们写成光刻机的成像机制。</p><h3 id="全反射不是「折射角等于-90°-的光线」" tabindex="-1">全反射不是「折射角等于 90° 的光线」 <a class="header-anchor" href="#全反射不是「折射角等于-90°-的光线」" aria-label="Permalink to &quot;全反射不是「折射角等于 90° 的光线」&quot;">​</a></h3><p>\\(\\theta_i=\\theta_c\\) 时 \\(\\theta_t=90^\\circ\\)，透射波沿界面掠射。\\(\\theta_i\\gt \\theta_c\\) 时 \\(\\sin\\theta_t\\gt 1\\)，折射角不再是实数，透射侧场沿界面传播、沿法向指数衰减。能量在无吸收时全部反射，\\(|r_s|=|r_p|=1\\)，但场仍然渗进疏媒约一个波长。把 TIR 理解成「光线在界面折回、对面什么都没有」，会丢掉近场耦合。</p><p><span class="marginnote">Brewster 角 \\(\\theta_B=\\arctan(n_2/n_1)\\)（从 \\(n_1\\) 到 \\(n_2\\)）。此时反射线与折射线垂直，\\(r_p=0\\)。临界角 \\(\\theta_c=\\arcsin(n_2/n_1)\\)，仅当 \\(n_1\\gt n_2\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令上一课的 \\(r_p=0\\)，得到 \\(\\theta_i+\\theta_t=90^\\circ\\)，即 Brewster 条件。反射光为纯 s 线偏振（入射若含 p，p 分量全部进入折射）。全内反射：\\(n_1\\gt n_2\\) 且 \\(\\theta_i\\gt \\theta_c\\)。透射侧波矢的法向分量变成虚数，倏逝波振幅 \\(\\propto e^{-\\kappa z}\\)，\\(\\kappa=\\frac{2\\pi}{\\lambda}\\sqrt{n_1^2\\sin^2\\theta_i-n_2^2}\\)，穿透深度约 \\(\\lambda\\) 量级。</p><p>无吸收时功率不进入疏媒，但相位 \\(\\arg r\\) 随入射角变化，伴随 Goos–Hänchen 横向位移。本课只记 \\(|r|=1\\) 与衰减，精细相位计量留给后课。</p>',12)),(t(),p(h,null,{default:r(()=>[_(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FRES%5B%22%E8%8F%B2%E6%B6%85%E5%B0%94%20r_s%2C%20r_p%22%5D%20--%3E%20BR%5B%22Brewster%3A%20r_p%3D0%22%5D%0A%20%20FRES%20--%3E%20TIR%5B%22%CE%B8%20%E5%A4%A7%E4%BA%8E%E4%B8%B4%E7%95%8C%E8%A7%92%22%5D%0A%20%20TIR%20--%3E%20EVAN%5B%22%E5%80%8F%E9%80%9D%E6%B3%A2%E6%B3%95%E5%90%91%E8%A1%B0%E5%87%8F%22%5D%0A%20%20BR%20--%3E%20POL%5B%22%E5%8F%8D%E5%B0%84%E5%85%89%E4%B8%BA%E7%BA%AF%20s%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Brewster 用于降低窗片 p 反射，或构造偏振敏感取样。TIR 在棱镜、光纤与某些对准传感器里作转向：损耗主要来自镀膜与散射，不是「折射把能量带走」。倏逝场随距离指数掉，只有把另一块光密媒凑到衰减长度内（受抑全反射）才会把能量再耦合出去。</p><p>浸没光刻的末片与晶圆之间是液体，设计上要让工作角度落在传播区，避免在液体–空气或液体–膜界面误入 TIR 而丢光。临界角语言在这里是警告，不是成像手段。高 NA 下大角度已经靠近一些界面的临界区，\\(R_s\\) 与 \\(R_p\\) 分叉加剧，这与上一课的矢量效应是同一条线。</p><p>Brewster 角随折射率比移动：浸没或镀膜会把 \\(\\theta_B\\) 挪到另一处，窗片「不反 p」的角度不能从空气–玻璃表上抄来就用。TIR 的相位随角度变，还被用来做移相元件；本课不把移相掩模提前讲完，只承认全反射系数是复数、模为 1。下一课薄膜把「半无限」改成有限 \\(d\\)，这两个特殊角仍作为单界面的极限出现在膜系公式里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假定两均匀半无限介质、实折射率。有限厚度疏媒上的受抑全反射、金属表面的等离子体反射，不在本课。也不把 TIR 当成扫描投影的成像原理——物镜靠折射与镜面，不是棱镜全反射把掩模搬到晶圆。</p><p>下一课 <a href="/litho/thin-film-interference">薄膜干涉</a> 把单界面换成有限厚度，多束反射相干叠加。后课默认：Brewster 与 TIR 是菲涅尔的两个极限，倏逝波有穿透深度，主成像链仍用传播平面波。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Brewster 角：\\(r_p=0\\)，反射光为线偏 s。</li><li>全内反射：\\(\\theta_i\\gt \\theta_c\\) 时 \\(|r|=1\\)，疏媒侧为倏逝波。</li><li>倏逝场渗入约一个波长；近场耦合靠受抑全反射，不是本课主线。</li><li>投影成像通常不在 TIR 区；角概念用于光路与偏振。</li><li>出处：Hecht, <em>Optics</em>；Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',9))])}const b=s(c,[["render",d]]);export{A as __pageData,b as default};
